def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    if input_data is None:
        return []
    try:
        data = json.loads(input_data)
    except json.JSONDecodeError:
        return []
    recipients = data if isinstance(data, list) else [data]
    names = []
    emails = []
    for item in recipients:
        if not isinstance(item, dict):
            continue
        name = item.get("name")
        email = item.get("email")
        if name and email:
            names.append(name)
            emails.append(email)
    if not names or not emails:
        return names
    message = "Subject: Extracted Names\n\n" + "\n".join(names)
    try:
        server = smtp or smtplib.SMTP(smtp_server, smtp_port)
        if not smtp:
            server.starttls()
            server.login(email_address, email_password)
        for recipient_email in emails:
            server.sendmail(email_address, recipient_email, message)
        if not smtp:
            server.quit()
    except Exception:
        return names
    return names

