import pandas as pd
def task_func(json_str):
    if not json_str or not json_str.strip():
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()
    if not isinstance(data, dict):
        return pd.DataFrame()

    def is_number(value):
        try:
            float(value)
            return True
        except (ValueError, TypeError):
            return False

    def process_value(v):
        if isinstance(v, (int, float)):
            return float(v) * 2
        elif isinstance(v, list):
            new_list = []
            for item in v:
                if isinstance(item, (int, float)):
                    new_list.append(float(item) * 2)
                elif isinstance(item, str) and is_number(item):
                    new_list.append(float(item) * 2)
                else:
                    new_list.append(item)
            return new_list
        elif isinstance(v, str):
            if is_number(v):
                return float(v) * 2
            nums = re.findall(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', v)
            if nums:
                def replace_num(match):
                    num = float(match.group(0))
                    return str(num * 2)
                return re.sub(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', replace_num, v)
            return v
        else:
            return v

    processed = {}
    for k, v in data.items():
        processed[k] = process_value(v)

    try:
        df = pd.DataFrame(processed)
    except ValueError:
        try:
            df = pd.DataFrame([processed])
        except ValueError:
            df = pd.DataFrame()

    for col in df.columns:
        df[col] = pd.to_numeric(df[col], errors='ignore')
    return df

