    except Exception:
        raise ValueError("Malformed JSON data")
    if not data:
        raise ValueError("Empty JSON data")
    if not isinstance(data, list):
        raise ValueError("JSON data must be a list of records")
    countries = []
    populations = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each record must be a dict")
        if "Country" not in item or "Population" not in item:
            raise ValueError("Missing Country or Population field")
        country = item["Country"]
        population = item["Population"]
        if not isinstance(country, str):
            raise ValueError("Country name must be a string")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population must be non-negative")
        pop_int = math.floor(population)
        countries.append(country)
        populations.append(pop_int)
    df = pd.DataFrame({"Country": countries, "Population": populations})
    if not os.path.isdir(output_dir):
        raise IOError("Output directory does not exist")
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError(str(e))
    return file_path, df

